class Solution {
    public int countOrders(int n) {
        final long MOD = 1_000_000_007L;
        long ans = 1L;
        for (int i = 1; i <= n; i++) {
            ans = ans * i % MOD;
            ans = ans * (2 * i - 1) % MOD;
        }
        return (int) ans;
    }
}

