#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int countOrders(int n) {
        const int MOD = 1000000007;
        long long ans = 1;

        for (int i = 1; i <= n; ++i) {
            // Adding the i-th order multiplies by i * (2i - 1)
            ans = ans * i % MOD;
            ans = ans * (2 * i - 1) % MOD;
        }

        return (int)ans;
    }
};

